// Core entities
abstract class Vehicle {
  private String licensePlate;
  private VehicleType type;
  // getters
}
class Car extends Vehicle {}
class Motorcycle extends Vehicle {}

class ParkingSpot {
  private String spotId;
  private SpotType type;  // COMPACT, LARGE
  private boolean occupied;
  private Vehicle currentVehicle;

  public boolean canPark(Vehicle v) {
    return !occupied && type.canFit(v.getType());
  }
  public void park(Vehicle v) { occupied = true; currentVehicle = v; }
  public void vacate() { occupied = false; currentVehicle = null; }
}

interface FeeCalculator {
  BigDecimal calculate(ParkingTicket ticket);
}

class HourlyFeeCalculator implements FeeCalculator {
  private final Map<VehicleType, BigDecimal> hourlyRates;

  public BigDecimal calculate(ParkingTicket ticket) {
    long hours = ChronoUnit.HOURS.between(
        ticket.getEntryTime(), LocalDateTime.now());
    return hourlyRates.get(ticket.getVehicle().getType())
        .multiply(BigDecimal.valueOf(Math.max(1, hours)));
  }
}

// Thread-safe spot assignment
public class ParkingSpot {
  private volatile boolean occupied = false;

  public synchronized boolean tryPark(Vehicle v) {
    if (occupied) return false;
    occupied = true;
    currentVehicle = v;
    return true;
  }
}

// Or use AtomicBoolean for lock-free:
private final AtomicBoolean occupied = new AtomicBoolean(false);
public boolean tryPark(Vehicle v) {
  if (occupied.compareAndSet(false, true)) {
    currentVehicle = v; return true;
  }
  return false;
}
